/* MIT. Wading uses existing water coverage plus collision and bridge-aware height. */
static int world_in_water(void*unused,float x,float y,float nx,float ny){(void)unused;(void)nx;(void)ny;if(!water_map_valid51a(activeMap)||!allowed(x,y)||height_at(x,y)>waterMaps[activeMap].z+.1f)return 0;for(unsigned i=waterMaps[activeMap].start,end=i+waterMaps[activeMap].count;i<end;i++){const unsigned short*r=waterRects[i];if(x>=r[0]&&x<r[2]&&y>=r[1]&&y<r[3])return 1;}return 0;}
static int world_test_water(Combat*g){if(!water_map_valid51a(activeMap)){combat_message(g,"Water data unavailable for this area.");return 0;}float best=1e30f,bx=0,by=0;for(unsigned i=waterMaps[activeMap].start,end=i+waterMaps[activeMap].count;i<end;i++){const unsigned short*r=waterRects[i];for(float y=r[1]+4;y<r[3];y+=8)for(float x=r[0]+4;x<r[2];x+=8){float d=(g->x-x)*(g->x-x)+(g->y-y)*(g->y-y);if(d<best&&world_in_water(NULL,x,y,x,y)){best=d;bx=x;by=y;}}}if(best==1e30f){combat_message(g,"No walkable wading spot on this map. Try West Field.");return 0;}g->x=bx;g->y=by;g->target=-1;g->autoAttack=0;combat_message(g,"Moved to shallow water for Aqua Benedicta testing.");return 1;}
